<template>
  <div class="app">
    <header><div><small>COMFYUI · MINIMAX H3</small><h1>多模式导演台</h1><p>按原版导演流水线配置分段、参考素材和输出参数。</p></div><nav><a href="/?mode=storyboard">九宫格分镜</a><a href="/?mode=i2v">I2V 首帧</a><a class="active" href="/?mode=director">多模式导演台</a><a href="/?mode=nine-images">九图分镜版</a><a href="/?mode=tasks">任务管理</a><a href="/?mode=system">系统信息</a></nav></header>
    <main>
      <section class="card settings"><h2>全局设置</h2>
        <label>ComfyUI 服务地址<input v-model.trim="server" /></label>
        <label>生成模式<select v-model="mode" @change="loadDefaults"><option v-for="m in modes" :key="m.id" :value="m.id">{{ m.label }}</option></select></label>
        <label>全局提示词<textarea v-model="globalPrompt" rows="6" placeholder="对整段视频生效的角色、场景、风格要求" /></label>
        <div class="params"><label>输出比例<select v-model="aspect"><option>9:16 (竖屏)</option><option>16:9 (横屏)</option><option>1:1 (方形)</option></select></label><label>像素规模（MP）<select v-model.number="mp"><option :value="0.4">0.4</option><option :value="0.6">0.6</option><option :value="0.8">0.8</option></select></label><label>尺寸对齐倍数<select v-model.number="multiple"><option :value="16">16</option><option :value="32">32</option><option :value="64">64</option></select></label><label>帧率<input v-model.number="fps" type="number" min="12" max="30" /></label><label>采样步数<input v-model.number="steps" type="number" min="1" max="50" /></label><label>随机种子<input v-model.number="seed" type="number" /></label></div>
        <label v-if="needsReferences">参考主体图片 <span>可多选</span><input type="file" accept="image/*" multiple @change="addReferences" /></label>
        <div v-if="references.length" class="chips"><span v-for="(f,i) in references" :key="f.name+i">{{ f.name }} <button @click="references.splice(i,1)">×</button></span></div>
        <label v-if="needsVideo">参考视频 <em>必选</em><input type="file" accept="video/*" @change="setVideo" /></label><p v-if="video" class="file">{{ video.name }}</p>
      </section>
      <section class="card timeline"><div class="title"><div><h2>分段时间线</h2><p>最多 5 段。首尾帧模式会将上一段的尾帧作为下一段的首帧。</p></div><button class="small" :disabled="segments.length>=5" @click="addSegment">添加一段</button></div>
        <div class="segments"><article v-for="(s,i) in segments" :key="s.id"><div class="segment-title"><b>片段 {{ i+1 }}</b><button v-if="segments.length>1" class="icon" @click="segments.splice(i,1)">删除</button></div><div class="segment-grid"><label>时长（秒）<input v-model.number="s.duration" type="number" min="1" max="10" step=".5" /></label><label>片段提示词<textarea v-model="s.prompt" rows="3" placeholder="本段动作、镜头、音效" /></label></div><div v-if="needsStartEnd" class="frames"><label>首帧图片 <em>必选</em><input type="file" accept="image/*" @change="setFrame($event,s,'start')" /><img v-if="s.start.preview" :src="s.start.preview" /></label><label>尾帧图片 <em>必选</em><input type="file" accept="image/*" @change="setFrame($event,s,'end')" /><img v-if="s.end.preview" :src="s.end.preview" /></label></div><label v-else-if="needsStart">首帧图片 <em>必选</em><input type="file" accept="image/*" @change="setFrame($event,s,'start')" /><img v-if="s.start.preview" :src="s.start.preview" /></label></article></div>
        <button class="generate" :disabled="running" @click="submit">{{ running?'正在生成…':'提交导演任务' }}</button>
      </section>
      <section class="card result"><h2>任务状态</h2><p v-if="!job" class="muted">尚未提交任务。</p><template v-else><p><strong :class="job.status">{{ statusName }}</strong> <code>{{job.id||'正在上传素材…'}}</code></p><pre>{{job.log}}</pre><video v-if="job.video" :src="job.video" controls></video><a v-if="job.video" :href="job.video" target="_blank">打开 / 下载结果</a></template></section>
    </main>
  </div>
</template>

<script setup>
import {computed,ref} from 'vue'
import fl2vTemplate from './assets/minimax_h3_director_fl2v.api.json'
import i2vTemplate from './assets/minimax_h3_director_i2v.api.json'
import r2vTemplate from './assets/minimax_h3_director_r2v.api.json'
import rv2vTemplate from './assets/minimax_h3_director_rv2v_20260817.api.json'
import t2vTemplate from './assets/minimax_h3_director_t2v.api.json'
import v2vTemplate from './assets/minimax_h3_director_v2v.api.json'
const server=ref('http://192.168.8.231:8188'),mode=ref('fl2v'),globalPrompt=ref(''),aspect=ref('9:16 (竖屏)'),mp=ref(.4),multiple=ref(32),fps=ref(30),steps=ref(20),seed=ref(666),references=ref([]),video=ref(null),running=ref(false),job=ref(null)
const modes=[{id:'t2v',label:'t2v — 文生视频'},{id:'i2v',label:'i2v — 图生视频'},{id:'fl2v',label:'fl2v — 首尾帧生视频'},{id:'r2v',label:'r2v — 参考主体生视频'},{id:'v2v',label:'v2v — 视频转视频'},{id:'rv2v',label:'rv2v — 参考素材改视频'}]
const workflowTemplates={t2v:t2vTemplate,i2v:i2vTemplate,fl2v:fl2vTemplate,r2v:r2vTemplate,v2v:v2vTemplate,rv2v:rv2vTemplate}
const clone=value=>JSON.parse(JSON.stringify(value))
const segment=(source={})=>({id:source.id||`segment-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,duration:source.durationSec||5,prompt:source.prompt||'',start:{file:null,preview:'',existing:source.genImage||null},end:{file:null,preview:'',existing:source.endImage||null}}),segments=ref([])
const needsStart=computed(()=>['i2v','fl2v'].includes(mode.value)),needsStartEnd=computed(()=>mode.value==='fl2v'),needsReferences=computed(()=>['r2v','rv2v'].includes(mode.value)),needsVideo=computed(()=>['v2v','rv2v'].includes(mode.value))
const statusName=computed(()=>({uploading:'上传中',queued:'等待中',running:'生成中',completed:'已完成',error:'失败'}[job.value?.status]||'处理中'))
function loadDefaults(){const i=workflowTemplates[mode.value]['12'].inputs,t=JSON.parse(i.timeline_data),o=t.output||{};globalPrompt.value=i.global_prompt||t.global?.prompt||'';aspect.value=o.aspectRatio||aspect.value;mp.value=o.megapixels??mp.value;multiple.value=o.multiple??multiple.value;fps.value=i.frame_rate||fps.value;steps.value=i.steps||steps.value;seed.value=i.seed??seed.value;segments.value=(t.segments||[]).map(segment);if(!segments.value.length)segments.value=[segment()];references.value=[];video.value=null} function addSegment(){segments.value.push(segment())} function setFrame(e,s,k){const f=e.target.files?.[0];if(f)s[k]={file:f,preview:URL.createObjectURL(f)}} function addReferences(e){references.value.push(...Array.from(e.target.files||[]))} function setVideo(e){video.value=e.target.files?.[0]||null} loadDefaults()
async function upload(file){const body=new FormData();body.append('image',file,file.name);body.append('overwrite','true');const r=await fetch(`${server.value}/upload/image`,{method:'POST',body});if(!r.ok)throw Error(`素材上传失败：HTTP ${r.status}`);return r.json()}
async function imageInfo(file){if(!file)return {imageFile:'',width:0,height:0};const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();return {imageFile:'',width:im.naturalWidth,height:im.naturalHeight}}finally{URL.revokeObjectURL(url)}}
function dimensions(){const long=mp.value<=.4?864:1024;let w=aspect.value.startsWith('9:16')?Math.round(long*9/16):aspect.value.startsWith('16:9')?long:long;let h=aspect.value.startsWith('9:16')?long:aspect.value.startsWith('16:9')?Math.round(long*9/16):long;return {width:Math.round(w/multiple.value)*multiple.value,height:Math.round(h/multiple.value)*multiple.value,long}}
async function build(){const w=clone(workflowTemplates[mode.value]),i=w['12'].inputs,t=JSON.parse(i.timeline_data),d=dimensions(),label=i.task_type;const uploads=new Map();const put=async f=>{if(!f)return null;if(!uploads.has(f))uploads.set(f,await upload(f));return uploads.get(f)};for(const s of segments.value){s.start.up=await put(s.start.file);s.end.up=await put(s.end.file)}const refs=[];for(const f of references.value){const up=await put(f),info=await imageInfo(f);refs.push({index:refs.length,imageFile:up.name,fileName:up.name,type:'input',subfolder:'',...info})}const v=await put(video.value),frameUnit=mode.value==='fl2v'?158/5:124/5;let start=0;const built=[];for(const s of segments.value){const len=Math.round(s.duration*frameUnit),si=s.start.file?await imageInfo(s.start.file):clone(s.start.existing||{imageFile:'',width:0,height:0}),ei=s.end.file?await imageInfo(s.end.file):clone(s.end.existing||{imageFile:'',width:0,height:0});if(s.start.up){si.imageFile=s.start.up.name;si.fileName=s.start.up.name}if(s.end.up){ei.imageFile=s.end.up.name;ei.fileName=s.end.up.name}built.push({id:s.id,start,length:len,frameCount:len,durationSec:s.duration,prompt:s.prompt,negativePrompt:'bad video',isStartFrame:!!si.imageFile,isEndFrame:!!ei.imageFile,genImage:si,endImage:ei.imageFile?ei:null,taskType:'',refs,refAudios:[],refVideos:[],...(v?{referenceVideo:{videoFile:v.name,fileName:v.name,type:'input',subfolder:''},_videoFrameCount:len,previewFps:fps.value}:{})});start+=len}t.global.taskType=label;t.global.prompt=globalPrompt.value;t.global.refs=refs;t.global.referenceVideo=v?{videoFile:v.name,fileName:v.name,type:'input',subfolder:''}:{videoFile:'',fileName:'',type:'input',subfolder:''};t.output.aspectRatio=aspect.value;t.output.megapixels=mp.value;t.output.multiple=multiple.value;t.output.longEdge=d.long;t.output.width=d.width;t.output.height=d.height;t.segments=built;t.shots=built.map(s=>({id:s.id,durationSec:s.duration,prompt:s.prompt,negativePrompt:s.negativePrompt,startImage:s.genImage,endImage:s.endImage}));if(mode.value==='fl2v')t.keyframes=built.flatMap(s=>{const half=Math.floor(s.length/2),items=[];if(s.genImage?.imageFile)items.push({id:`${s.id}_s`,imageFile:s.genImage.imageFile,width:s.genImage.width||0,height:s.genImage.height||0,start:s.start,length:s.endImage?.imageFile?half:s.length,frameCount:s.endImage?.imageFile?half:s.length,durationSec:s.duration,prompt:s.prompt,negativePrompt:s.negativePrompt,isStartFrame:true,isEndFrame:false});if(s.endImage?.imageFile)items.push({id:`${s.id}_e`,imageFile:s.endImage.imageFile,width:s.endImage.width||0,height:s.endImage.height||0,start:s.start+half,length:s.length-half,frameCount:s.length-half,durationSec:s.duration,prompt:'',negativePrompt:s.negativePrompt,isStartFrame:false,isEndFrame:true});return items});t.totalFrames=start;t.durationSec=segments.value.reduce((n,s)=>n+s.duration,0);t.width=d.width;t.height=d.height;i.global_prompt=globalPrompt.value;i.frame_rate=fps.value;i.width=d.width;i.height=d.height;i.ref_max_size=d.long;i.total_frames=start;i.steps=steps.value;i.seed=seed.value;i.timeline_data=JSON.stringify(t);return w}
function valid(){if(needsStart.value&&segments.value.some(s=>!s.start.file&&!s.start.existing?.imageFile))return '请为每个片段上传首帧图片';if(needsStartEnd.value&&segments.value.some(s=>!s.end.file&&!s.end.existing?.imageFile))return '请为每个片段上传尾帧图片';if(needsReferences.value&&!references.value.length)return '请至少上传一张参考主体图片';if(needsVideo.value&&!video.value)return '请上传参考视频';return ''}
async function submit(){const err=valid();if(err)return alert(err);running.value=true;job.value={status:'uploading',id:'',log:'正在上传素材…',video:''};try{const w=await build(),r=await fetch(`${server.value}/prompt`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:w})}),data=await r.json();if(!r.ok||data.error)throw Error(data.error?.message||data.error||`提交失败：HTTP ${r.status}`);job.value={status:'queued',id:data.prompt_id,log:`任务已提交：${data.prompt_id}`,video:''};poll()}catch(e){job.value.status='error';job.value.log+=`\n错误：${e.message}`;running.value=false}}
async function poll(){try{const data=await (await fetch(`${server.value}/history/${job.value.id}`)).json(),entry=data[job.value.id];if(!entry){job.value.status='queued'}else if(entry.status?.status_str==='error')throw Error('ComfyUI 执行失败');else if(entry.status?.completed){job.value.status='completed';job.value.video=out(entry.outputs||{});job.value.log+=job.value.video?'\n视频已生成。':'\n执行完成，但未找到视频输出。';running.value=false;return}else job.value.status='running';setTimeout(poll,2500)}catch(e){job.value.status='error';job.value.log+=`\n错误：${e.message}`;running.value=false}}
function out(outputs){for(const n of Object.values(outputs))for(const k of ['images','gifs','videos']){const f=n[k]?.find(x=>x.filename);if(f)return `${server.value}/view?${new URLSearchParams({filename:f.filename,subfolder:f.subfolder||'',type:f.type||'output'})}`}return ''}
</script>

<style scoped>
:global(:root){font-family:Inter,system-ui,"Microsoft YaHei",sans-serif;color:#e7edf7;background:#101825}:global(body){margin:0}.app{max-width:1450px;margin:auto;padding:30px}header{display:flex;justify-content:space-between;gap:20px;margin:10px 0 28px}small{color:#7dd3fc;letter-spacing:.12em;font-weight:700}h1{margin:8px 0;font-size:32px}h2{margin:0 0 10px;font-size:18px}p,.muted{color:#9eb0cb;margin:0}nav{display:flex;gap:8px;height:max-content}nav a{color:#c9d5e7;text-decoration:none;padding:8px 11px;border:1px solid #2a3a53;border-radius:8px;font-size:13px;white-space:nowrap}nav .active{color:#062034;background:#67e8f9;border-color:#67e8f9}main{display:grid;grid-template-columns:360px 1fr;gap:20px}.card{background:#172233;border:1px solid #2a3a53;border-radius:16px;padding:22px;box-shadow:0 16px 40px #0002}.settings{grid-row:span 2}label{display:block;color:#c9d5e7;font-size:13px;font-weight:600;margin-top:13px}label span{color:#7dd3fc;font-weight:400}em{color:#fbbf24;font-style:normal}input,select,textarea{width:100%;margin-top:6px;color:#ecf5ff;background:#0f1725;border:1px solid #3a4e6d;border-radius:8px;padding:9px;font:inherit}textarea{resize:vertical}.params{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}.title,.segment-title{display:flex;justify-content:space-between;gap:14px;align-items:start}.segments{display:grid;gap:12px;margin-top:16px}article{background:#111a28;border:1px solid #2a3a53;border-radius:11px;padding:14px}.segment-title b{color:#7dd3fc}.segment-title button,.chips button{width:auto;margin:0;background:none;border:0;color:#fca5a5;padding:0;cursor:pointer}.segment-grid,.frames{display:grid;grid-template-columns:150px 1fr;gap:12px}.frames{grid-template-columns:1fr 1fr}.frames img{display:block;width:100%;height:100px;object-fit:contain;background:#0b1019;margin-top:8px;border-radius:7px}.small{width:auto;margin:0;padding:9px 13px}.generate{margin-top:18px}.chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.chips span,.file{font-size:12px;color:#b7e4f8;background:#123449;padding:5px 8px;border-radius:6px}button{width:100%;margin-top:18px;border:0;padding:13px;border-radius:10px;font-size:15px;font-weight:700;color:#062034;background:linear-gradient(90deg,#67e8f9,#38bdf8);cursor:pointer}button:disabled{opacity:.55;cursor:wait}strong{padding:5px 10px;border-radius:99px;font-size:12px}.uploading,.queued{color:#fde68a;background:#41381d}.running{color:#7dd3fc;background:#173c55}.completed{color:#86efac;background:#163827}.error{color:#fca5a5;background:#4b2029}code{margin-left:10px;color:#c9d5e7;font-size:12px;word-break:break-all}pre{white-space:pre-wrap;background:#0d1420;border:1px solid #293950;padding:12px;border-radius:8px;font-size:12px;max-height:180px;overflow:auto}.result video{display:block;width:100%;background:#000;border-radius:10px;margin-top:14px}.result a{display:inline-block;margin-top:12px;color:#7dd3fc}@media(max-width:980px){main{grid-template-columns:1fr}.settings{grid-row:auto}}@media(max-width:650px){.app{padding:18px}header{display:block}nav{margin-top:14px;flex-wrap:wrap}.segment-grid,.frames,.params{grid-template-columns:1fr}}
</style>
